138	    /**
139	     * Derives the owner's age band from the birth date, measured against the registration date:
140	     * {@code 'MINOR'} when under 18, {@code 'ADULT'} for 18 to 64 inclusive, and {@code 'SENIOR'}
141	     * from 65 on. Returns {@code null} when either the birth date or the registration date is absent,
142	     * so an owner created without a birth date has no age band.
143	     */
144	    @Transient
145	    public String getAgeBand() {
146	        if (this.birthDate == null || this.registrationDate == null) {
147	            return null;
148	        }
149	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
150	        if (age < 18) {
151	            return "MINOR";
152	        }
153	        return age < 65 ? "ADULT" : "SENIOR";
