180	    /**
181	     * Whether this owner was flagged a possible (soft-match) duplicate at creation: it was not a
182	     * hard duplicate, yet it shared an existing owner's lastName and postcode while carrying a
183	     * different telephone. False when no such match existed.
184	     */
185	    public Boolean getPossibleDuplicate() {
186	        return this.possibleDuplicate;
187	    }
