207	     * the normalized telephone, the email (empty when absent) and the household id (empty
208	     * when absent), joined with {@code '|'}. Two owners are duplicates only when their whole
209	     * identity keys are equal, so any single differing component (telephone, email or
210	     * household) yields distinct keys and is allowed. Derived from persisted fields, so it is
211	     * not itself a persistent column.
212	     */
213	    @Transient
214	    public String getIdentityKey() {
215	        return (this.telephone == null ? "" : this.telephone)
216	            + "|" + (this.email == null ? "" : this.email)
217	            + "|" + (this.householdId == null ? "" : this.householdId);
218	    }
