226	        resolveRegistrationDate();
227	    }
228	
229	    /**
230	     * Resolves this owner's effective registration date and stores it: the supplied value is used, or
231	     * the server's current date when none was supplied, and the result is rolled forward onto a
232	     * business day (a Saturday or Sunday becomes the following Monday). Returns the resolved date.
233	     * Idempotent, so it is safe to call from both the create flow and the persist hook.
234	     */
235	    public LocalDate resolveRegistrationDate() {
236	        LocalDate effective = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
237	        this.registrationDate = toBusinessDay(effective);
238	        return this.registrationDate;
239	    }
240	
241	    /**
242	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
243	     * following Monday, while any weekday (and {@code null}) is returned unchanged. Applying this to a
244	     * date that is already a business day is a no-op, so it is safe to call more than once.
245	     */
246	    public static LocalDate toBusinessDay(LocalDate date) {
247	        if (date == null) {
248	            return null;
249	        }
250	        return switch (date.getDayOfWeek()) {
251	            case SATURDAY -> date.plusDays(2);
252	            case SUNDAY -> date.plusDays(1);
253	            default -> date;
254	        };
255	    }
256	
257	    protected Set<Pet> getPetsInternal() {
258	        if (this.pets == null) {
259	            this.pets = new HashSet<>();
260	        }
261	        return this.pets;
262	    }
263	
264	    protected void setPetsInternal(Set<Pet> pets) {
265	        this.pets = pets;
