267	
268	    public List<Pet> getPets() {
269	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
270	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
271	        return Collections.unmodifiableList(sortedPets);
272	    }
273	
