249	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
250	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
251	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
252	
253	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
254	     *  when deriving an owner's region. */
255	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
256	        "NSW", new int[] {2000, 2099},
257	        "VIC", new int[] {3000, 3099},
258	        "QLD", new int[] {4000, 4099});
259	
260	    /**
261	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
262	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
263	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
264	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
265	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
266	     */
267	    private String generateCustomerCode(Owner owner) {
268	        return String.format("%s-%s", deriveRegion(owner), hash8(owner));
269	    }
270	
271	    /**
272	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
273	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
274	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
275	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
276	     * city is not in the table.
277	     */
278	    private static String deriveRegion(Owner owner) {
279	        String postcode = owner.getPostcode();
280	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
281	            int value = Integer.parseInt(postcode);
282	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
283	                int[] range = entry.getValue();
284	                if (value >= range[0] && value <= range[1]) {
285	                    return entry.getKey();
286	                }
287	            }
288	        }
289	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
290	    }
291	
292	    /**
293	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
294	     * digest over its normalized telephone concatenated with its last name.
295	     */
296	    private static String hash8(Owner owner) {
297	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
298	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
299	        String seed = telephone + lastName;
300	        try {
301	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
302	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
303	            StringBuilder sb = new StringBuilder(hash.length * 2);
304	            for (byte b : hash) {
305	                sb.append(String.format("%02X", b));
306	            }
307	            return sb.substring(0, 8);
308	        }
309	        catch (NoSuchAlgorithmException e) {
310	            throw new IllegalStateException("SHA-256 not available", e);
311	        }
312	    }
313	
314	    /**
315	     * Whether any existing owner has the given derived identity key. This is the single basis for
316	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
317	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
318	     */
319	    @Override
320	    @Transactional(readOnly = true)
321	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
322	        if (identityKey == null) {
323	            return false;
324	        }
325	        return ownerRepository.findAll().stream()
326	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
327	    }
328	
329	    /**
330	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
331	     * that shares its lastName (case-insensitive) and postcode while carrying a <i>different</i>
332	     * telephone. This is a weaker match than the hard-duplicate identity key, so it is only meaningful
333	     * for an owner that is not itself a hard duplicate. When several owners match, the one with the
334	     * lowest id is returned; {@code null} is returned when there is no match (or lastName/postcode is
335	     * absent), meaning the owner is not a possible duplicate.
336	     */
337	    @Override
338	    @Transactional(readOnly = true)
339	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
340	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
341	            return null;
342	        }
343	        String lastName = owner.getLastName();
344	        String postcode = owner.getPostcode();
345	        String telephone = owner.getTelephone();
346	        return ownerRepository.findAll().stream()
347	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
348	                && postcode.equals(existing.getPostcode())
349	                && !Objects.equals(telephone, existing.getTelephone()))
350	            .map(Owner::getId)
351	            .filter(Objects::nonNull)
352	            .min(Comparator.naturalOrder())
353	            .orElse(null);
354	    }
