402	    @Override
403	    @Transactional(readOnly = true)
404	    public boolean existsOwnerInHousehold(String lastName, String address) throws DataAccessException {
405	        return !findHouseholdMembers(lastName, address).isEmpty();
406	    }
407	
408	    /**
409	     * Returns the existing owners that belong to the household identified by the given last name
410	     * and address, comparing both fields in their normalized form. An empty list is returned when
411	     * either field is absent (no household can be formed).
412	     */
413	    private List<Owner> findHouseholdMembers(String lastName, String address) {
414	        String normalizedLastName = normalizeHouseholdField(lastName);
415	        String normalizedAddress = normalizeHouseholdAddress(address);
416	        if (normalizedLastName == null || normalizedAddress == null) {
417	            return List.of();
418	        }
419	        return ownerRepository.findAll().stream()
420	            .filter(existing -> normalizedLastName.equals(normalizeHouseholdField(existing.getLastName()))
421	                && normalizedAddress.equals(normalizeHouseholdAddress(existing.getAddress())))
422	            .toList();
423	    }
424	
425	    /**
426	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
427	     * runs of whitespace to a single space and lower-casing, so values that differ only in
428	     * whitespace or letter case are treated as equal.
429	     */
430	    private static String normalizeHouseholdField(String value) {
431	        if (value == null) {
432	            return null;
433	        }
434	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
435	    }
436	
437	    /**
438	     * Normalizes an address for household comparison and identity using the same canonical form
439	     * applied when an owner is created (trim/collapse whitespace, upper-case, expand common
440	     * abbreviations), so comparisons always use the normalized address regardless of the form in
441	     * which either value was originally supplied. Returns {@code null} when the address is absent
442	     * or blank, since no household can be formed without one.
443	     */
444	    private static String normalizeHouseholdAddress(String address) {
445	        String normalized = AddressNormalizer.normalize(address);
446	        if (normalized == null || normalized.isBlank()) {
447	            return null;
448	        }
449	        return normalized;
450	    }
451	
452	    /**
453	     * Places {@code owner} into the household formed by owners that share its (normalized) last
454	     * name and address, and returns the household's stable shared identifier. If any existing
455	     * member already carries a household id it is reused; otherwise a stable id is derived from
456	     * the shared last name and address. Every member missing an id (including the given owner)
457	     * is assigned the shared value so all owners in the household agree on it.
458	     */
459	    @Override
460	    @Transactional
461	    public String assignHousehold(Owner owner) throws DataAccessException {
462	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
463	        if (members.isEmpty()) {
464	            return null;
465	        }
466	        String householdId = members.stream()
467	            .map(Owner::getHouseholdId)
468	            .filter(id -> id != null && !id.isBlank())
469	            .findFirst()
470	            .orElseGet(() -> generateHouseholdId(owner.getLastName(), owner.getAddress()));
471	        for (Owner member : members) {
472	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
473	                member.setHouseholdId(householdId);
474	                ownerRepository.save(member);
475	            }
476	        }
477	        owner.setHouseholdId(householdId);
478	        return householdId;
479	    }
480	
481	    /**
482	     * Derives a stable household identifier from the normalized last name and address as the
483	     * first 16 upper-case hex characters of their SHA-256 digest, so the same household always
484	     * maps to the same value regardless of creation order.
485	     */
486	    private static String generateHouseholdId(String lastName, String address) {
487	        String seed = normalizeHouseholdField(lastName) + "\n" + normalizeHouseholdAddress(address);
488	        try {
489	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
490	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
491	            StringBuilder sb = new StringBuilder(hash.length * 2);
492	            for (byte b : hash) {
493	                sb.append(String.format("%02X", b));
494	            }
495	            return sb.substring(0, 16);
496	        }
497	        catch (NoSuchAlgorithmException e) {
498	            throw new IllegalStateException("SHA-256 not available", e);
499	        }
500	    }
