47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private static final Logger auditLogger = LoggerFactory.getLogger("AUDIT");
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
102	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
103	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
104	    }
105	
106	    /**
107	     * Whether more than 80 owners have already been created on {@code registrationDate},
108	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
109	     */
110	    private boolean isBulkSignup(LocalDate registrationDate) {
111	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        LocalDate registrationDate = owner.resolveRegistrationDate();
120	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
121	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
122	        }
123	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
124	            return new ResponseEntity<>(HttpStatus.CONFLICT);
125	        }
126	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
127	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getLastName(), owner.getAddress());
128	        if (sharesHousehold && householdExists) {
129	            this.clinicService.assignHousehold(owner);
130	        }
131	        // All duplicate detection is consolidated into the owner's derived identity key (see
132	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
133	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
134	            return new ResponseEntity<>(HttpStatus.CONFLICT);
135	        }
136	        // Soft-match: not a hard duplicate, but shares an existing owner's lastName and postcode with a
137	        // different telephone. Still created, flagged 'possibleDuplicate' with the matching owner's id.
138	        Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
139	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
140	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
141	        owner.setNamesakeCount(
142	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
143	        this.clinicService.saveOwner(owner);
144	        auditLogger.info("owner created: id={} customerCode={} registrationDate={}",
145	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
156	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
157	        if (currentOwner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        currentOwner.setAddress(ownerFieldsDto.getAddress());
161	        currentOwner.setCity(ownerFieldsDto.getCity());
162	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	        currentOwner.setLastName(ownerFieldsDto.getLastName());
164	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
165	        currentOwner.setEmail(ownerFieldsDto.getEmail());
166	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
167	        this.clinicService.saveOwner(currentOwner);
168	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Transactional
173	    @Override
174	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        this.clinicService.deleteOwner(owner);
180	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        HttpHeaders headers = new HttpHeaders();
191	        Pet pet = petMapper.toPet(petFieldsDto);
192	        owner.setId(ownerId);
193	        pet.setOwner(owner);
194	        pet.getType().setName(null);
195	        this.clinicService.savePet(pet);
196	        PetDto petDto = petMapper.toPetDto(pet);
197	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
198	            .buildAndExpand(pet.getId()).toUri());
199	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
205	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
206	        if (currentOwner != null) {
207	            Pet currentPet = this.clinicService.findPetById(petId);
208	            if (currentPet != null) {
209	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
210	                currentPet.setName(petFieldsDto.getName());
211	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
212	                this.clinicService.savePet(currentPet);
213	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
222	        HttpHeaders headers = new HttpHeaders();
223	        Visit visit = visitMapper.toVisit(visitFieldsDto);
224	        Pet pet = new Pet();
225	        pet.setId(petId);
226	        visit.setPet(pet);
227	        this.clinicService.saveVisit(visit);
228	        VisitDto visitDto = visitMapper.toVisitDto(visit);
229	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
230	            .buildAndExpand(visit.getId()).toUri());
231	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
232	    }
233	
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
238	        Owner owner = this.clinicService.findOwnerById(ownerId);
239	        if (owner != null) {
240	            Pet pet = owner.getPet(petId);
241	            if (pet != null) {
242	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	}
